-- pure-lua base64: guaranteed-correct binary decode, executor-independent
local B64CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64LOOKUP = {}
for CharIndex = 1, #B64CHARS do
	B64LOOKUP[B64CHARS:sub(CharIndex, CharIndex)] = CharIndex - 1
end

local function PureDecode(Data: string): string
	Data = Data:gsub("[^%w%+/=]", "")
	local Out, Buffer, Bits = {}, 0, 0
	for CharIndex = 1, #Data do
		local Char = Data:sub(CharIndex, CharIndex)
		if Char ~= "=" then
			Buffer = Buffer * 64 + (B64LOOKUP[Char] or 0)
			Bits = Bits + 6
			if Bits >= 8 then
				Bits = Bits - 8
				Out[#Out + 1] = string.char(math.floor(Buffer / (2 ^ Bits)) % 256)
				Buffer = Buffer % (2 ^ Bits)
			end
		end
	end
	return table.concat(Out)
end

local ExecutorDecode = nil
pcall(function()
	local Crypt = (typeof(crypt) == "table" and (crypt.base64decode or crypt.base64)) or (typeof(base64) == "table" and base64.decode) or base64_decode
	if type(Crypt) == "function" then
		ExecutorDecode = Crypt
	end
end)

-- verify the executor decoder against the pure one on a small sample;
-- some executors mangle binary base64, so trust only a proven match
local DecodeVerified = false
do
	local Sample = "AAECAwQFBgcICQ==" -- bytes 0x00..0x09
	local Pure = PureDecode(Sample)
	if ExecutorDecode then
		local OkExec, Exec = pcall(ExecutorDecode, Sample)
		if OkExec and Exec == Pure then
			DecodeVerified = true
		end
	end
end

local function Decode(B64: string): string
	if DecodeVerified and ExecutorDecode then
		local Ok, Result = pcall(ExecutorDecode, B64)
		if Ok and type(Result) == "string" then
			return Result
		end
	end
	return PureDecode(B64)
end

if not game:IsLoaded() then
	game.Loaded:Wait()
end
if shared.vapeloading and coroutine.status(shared.vapeloading) ~= "dead" then
	return
end
shared.vapeloading = coroutine.running()
if shared.vape then
	shared.vape:Uninject()
end

for _, Folder in {Directory, Directory.."/games", Directory.."/profiles", Directory.."/assets", Directory.."/libraries", Directory.."/guis"} do
	if not isfolder(Folder) then
		makefolder(Folder)
	end
end

local Installed = 0
for Rel, B64 in Embedded do
	local Dest = Directory .. "/" .. Rel
	local Parent = Dest:match("^(.+)/[^/]+$")
	if Parent and not isfolder(Parent) then
		makefolder(Parent)
	end
	local Ok, Content = pcall(Decode, B64)
	if Ok and type(Content) == "string" and #Content > 0 then
		-- never overwrite user profiles
		if not Dest:find("/profiles/") or not isfile(Dest) then
			local NeedsWrite = false
			if not isfile(Dest) then
				NeedsWrite = true
			elseif Rel:sub(-4) == ".lua" then
				-- content-diff: an outdated but compiling file must still update
				local OkRead, Existing = pcall(readfile, Dest)
				NeedsWrite = not OkRead or Existing ~= Content
			else
				local OkRead, Existing = pcall(readfile, Dest)
				NeedsWrite = not OkRead or Existing ~= Content
			end
			if NeedsWrite then
				writefile(Dest, Content)
			end
		end
		Installed = Installed + 1
	end
end
print("[slop] single-request boot: " .. Installed .. " files ready")

getgenv().catuser = "Slop"
getgenv().catrole = "premium"

local isfile = isfile or function(FilePath)
	local Success, Contents = pcall(function()
		return readfile(FilePath)
	end)
	return Success and Contents ~= nil and Contents ~= ""
end
local cloneref = cloneref or function(Reference) return Reference end
local Players = cloneref(game:GetService("Players"))
local HttpService = cloneref(game:GetService("HttpService"))

local License = { Key = "slop" }

local vape, RunPremium
local ls = function(...)
	local Chunk, Error = loadstring(...)
	if Error then
		warn("[slop] compile error: " .. tostring(Error))
	end
	return Chunk
end

if not isfile(Directory .. "/profiles/gui.txt") then
	writefile(Directory .. "/profiles/gui.txt", "new")
end
if not isfolder(Directory .. "/assets/new") then
	makefolder(Directory .. "/assets/new")
end
local GuiChunk = ls(readfile(Directory .. "/guis/new.lua"), "gui")
if not GuiChunk then
	error("[slop] gui failed to compile")
end
vape, RunPremium = GuiChunk(License)
shared.vape = vape
_G.vape = vape
getgenv().used_init = true

local function FinishLoading()
	vape.Init = nil
	vape:Load()
	shared.vapeloading = nil
	if not isfile(Directory .. "/profiles/notifications.txt") or readfile(Directory .. "/profiles/notifications.txt") ~= "false" then
		vape:CreateNotification("Finished Loading", "Slop single-request build - all systems loaded", 5)
	end
end

pcall(function() ls(readfile(Directory .. "/games/universal.lua"), "universal")(License) end)
pcall(function() ls(readfile(Directory .. "/games/" .. game.PlaceId .. ".lua"), tostring(game.PlaceId))(License) end)
pcall(function() ls(readfile(Directory .. "/libraries/main.lua"), "main")(License) end)
pcall(function() ls(readfile(Directory .. "/games/extras.lua"), "extras")() end)
pcall(function() ls(readfile(Directory .. "/games/staffdetector.lua"), "staff")() end)
pcall(function() ls(readfile(Directory .. "/games/spectatordetector.lua"), "spectator")() end)
pcall(function() ls(readfile(Directory .. "/games/cheatwatcher.lua"), "cheatwatcher")() end)
pcall(function() ls(readfile(Directory .. "/games/ghostfix.lua"), "ghostfix")() end)
pcall(function() ls(readfile(Directory .. "/games/aar.lua"), "aar")() end)
pcall(function() ls(readfile(Directory .. "/games/playui.lua"), "playui")() end)
FinishLoading()